def expected_row(name,b,spell_id=None):
 d,c,t,r,l,e=(DRUID_NAMES|WARLOCK_NAMES|MAGE_NAMES|SHAMAN_NAMES|NAMES|PALADIN_NAMES|HUNTER_NAMES|ROGUE_NAMES|PRIEST_NAMES)[name];spell=(DRUID_SPELLS|WARLOCK_SPELLS|MAGE_SPELLS|SHAMAN_SPELLS|SPELLS|PALADIN_SPELLS|HUNTER_SPELLS|ROGUE_SPELLS|PRIEST_SPELLS)[name]
 if spell_id in SHAMAN_SPELLS.values():
  d,c,t,r,l,e=SHAMAN_NAMES[name];spell=SHAMAN_SPELLS[name]
 if spell_id in WARLOCK_SPELLS.values():
  d,c,t,r,l,e=WARLOCK_NAMES[name];spell=WARLOCK_SPELLS[name]
 if spell_id in DRUID_SPELLS.values():
  d,c,t,r,l,e=DRUID_NAMES[name];spell=DRUID_SPELLS[name]
 if spell in (116,120,11113,8056):l*=e;e=1
 healing=HEALING.get(name,1)*(l if spell==774 else 1)
 native_damage=(1 if spell in (1130,118,770) else d)*(healing**2 if spell in (635,139,331,774,8936) else 1)
 return [b[0]*native_damage,b[1]*c,b[2]+t,b[3]*r,b[4]*l,b[5]*(1 if spell in (1130,118,770) else d),b[6]*e]
