def assess(output,glyphs_class="warrior"):
 names=DRUID_NAMES if glyphs_class=="druid"else WARLOCK_NAMES if glyphs_class=="warlock"else MAGE_NAMES if glyphs_class=="mage"else SHAMAN_NAMES if glyphs_class=="shaman"else PRIEST_NAMES if glyphs_class=="priest"else ROGUE_NAMES if glyphs_class=="rogue"else HUNTER_NAMES if glyphs_class=="hunter"else PALADIN_NAMES if glyphs_class=="paladin"else NAMES
 spells=DRUID_SPELLS if glyphs_class=="druid"else WARLOCK_SPELLS if glyphs_class=="warlock"else MAGE_SPELLS if glyphs_class=="mage"else SHAMAN_SPELLS if glyphs_class=="shaman"else PRIEST_SPELLS if glyphs_class=="priest"else ROGUE_SPELLS if glyphs_class=="rogue"else HUNTER_SPELLS if glyphs_class=="hunter"else PALADIN_SPELLS if glyphs_class=="paladin"else SPELLS
 logs=[(output/f"player-{i}/azeroth-coop-native.log").read_text(errors="replace")for i in (1,2)]
 host=logs[0];accepted=re.findall(r"glyph accepted: slot=(\d+) guid=\d+ spell=(\d+) rank=(\d+) glyph=([^\r\n]+)",host)
 mods=re.findall(r"glyph fixture modifiers: slot=(\d+) spell=(\d+) glyph=(.*?) before=(\[[^]]+\]) after=Ok\((\[[^]]+\])\)",host)
 casts=re.findall(r"glyph fixture native cast: slot=(\d+) spell=(\d+) rank=(\d+) glyph=([^\r\n]+?) modifiers=(\[[^]]+\])",host)
 good=bool(mods)
 for slot,spell,name,before,after in mods:
  b=json.loads(before);a=json.loads(after);expected=expected_row(name,b,int(spell))
  good=good and all(abs(x-y)<=max(.0001,abs(y)*.00001)for x,y in zip(a,expected))
 matrix=re.findall(r"glyph fixture (?:warrior|paladin|hunter|rogue|priest|shaman|mage|warlock|druid) matrix: slot=(\d+) spell=(\d+) glyph=(.*?) before=Ok\((\[[^]]+\])\) after=Ok\((\[[^]]+\])\)",host)
 matrix_ok=len(matrix)==len(names) and {row[2]for row in matrix}==set(names)
 for _,spell,name,before,after in matrix:
  b=json.loads(before);a=json.loads(after);expected=expected_row(name,b,int(spell))
  matrix_ok=matrix_ok and int(spell)==spells[name] and len(a)==7 and len(b)==7 and all(abs(x-y)<=max(.0001,abs(y)*.00001)for x,y in zip(a,expected))
 removed=re.findall(r"glyph fixture removal rebuilt: slot=(\d+) spell=(\d+) baseline=Some\((\[[^]]+\])\) current=Ok\((\[[^]]+\])\)",host)
 removal_ok=bool(removed) and all(json.loads(b)==json.loads(a) for _,_,b,a in removed)
 cards=[]
 for i in (1,2):
  text=(output/f"player-{i}/native-output.log").read_text(errors="replace")
  for line in text.splitlines():
   if line.startswith('rogue: {"type":"choices"'):
    cards.extend((i,c)for c in json.loads(line[7:]).get("choices",[])if "Glyph:" in c.get("lines",""))
 balanced=re.findall(r"glyph fixture XP balanced: (\[[^\r\n]+\])",host)
